// ── Structured logging with pino + correlation ID middleware ─────
import pino from 'pino';
import { randomUUID } from 'node:crypto';
import express from 'express';

// Base logger: JSON to stdout (pipe through pino-pretty in development).
// The LOG_LEVEL env var controls verbosity at deploy time.
const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  base: { service: 'order-service', version: process.env.APP_VERSION ?? 'unknown' },
  // Redact sensitive fields from every log record (paths are relative to the logged object):
  redact: ['req.headers.authorization', 'body.password', 'body.cardNumber'],
});

const app = express();
app.use(express.json());

// ── Middleware 1: Correlation ID ──────────────────────────────────
// Reuse the W3C trace ID if an upstream service sent traceparent;
// otherwise accept x-correlation-id; otherwise generate a new one.
app.use((req, res, next) => {
  const correlationId =
    extractTraceIdFromTraceparent(req.headers['traceparent']) ??
    req.headers['x-correlation-id'] ??
    randomUUID();

  req.correlationId = correlationId;
  // Echo the correlation ID back to the client for support use.
  res.setHeader('x-correlation-id', correlationId);

  // Bind the ID to a child logger — every req.log.* call includes it.
  req.log = logger.child({ correlationId, path: req.path, method: req.method });
  next();
});

// ── Middleware 2: Request lifecycle logging ───────────────────────
app.use((req, res, next) => {
  const startMs = performance.now();
  req.log.info({ event: 'request.start' });

  res.on('finish', () => {
    const durationMs = Math.round(performance.now() - startMs);
    // Choose log level based on HTTP status:
    const level =
      res.statusCode >= 500 ? 'error' :
      res.statusCode >= 400 ? 'warn'  : 'info';
    req.log[level]({ event: 'request.end', statusCode: res.statusCode, durationMs });
  });

  next();
});

// ── Route: Create order ───────────────────────────────────────────
app.post('/orders', async (req, res) => {
  const { userId, items = [] } = req.body ?? {};

  try {
    req.log.debug({ userId, itemCount: items.length }, 'Validating order');

    const order = await orderService.create(userId, items);   // your domain service

    req.log.info({ event: 'order.created', orderId: order.id, userId, total: order.total });
    res.status(201).json(order);
  } catch (err) {
    // pino's default serializer turns `err` into { type, message, stack }
    req.log.error({ event: 'order.failed', userId, err });
    res.status(500).json({ error: 'Order creation failed', correlationId: req.correlationId });
  }
});

// ── Propagating correlation ID to downstream service calls ────────
async function callPaymentService(req, payload) {
  return fetch('http://payment-service/charge', {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-correlation-id': req.correlationId,
      // With an OTel SDK, traceparent is injected automatically for fetch/http.
    },
    body: JSON.stringify(payload),
  });
}

function extractTraceIdFromTraceparent(header) {
  // Format: 00-{32-hex traceId}-{16-hex parentSpanId}-{2-hex flags}
  const m = /^[\da-f]{2}-([\da-f]{32})-[\da-f]{16}-[\da-f]{2}$/.exec(header ?? '');
  return m && m[1] !== '0'.repeat(32) ? m[1] : null;
}

app.listen(3000, () => logger.info({ event: 'server.started', port: 3000 }));

// ── File: otel.mjs — OpenTelemetry setup ──────────────────────────
// Load it before the app so instrumentation can patch modules:
//   node --import ./otel.mjs server.mjs
import { NodeSDK } from '@opentelemetry/sdk-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-grpc';
import { resourceFromAttributes } from '@opentelemetry/resources';
import { ATTR_SERVICE_NAME, ATTR_SERVICE_VERSION } from '@opentelemetry/semantic-conventions';
// Older releases export the samplers from '@opentelemetry/sdk-trace-base'
import { ParentBasedSampler, TraceIdRatioBasedSampler } from '@opentelemetry/sdk-trace';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';

const sdk = new NodeSDK({
  // Resource: metadata about THIS service, attached to every span.
  resource: resourceFromAttributes({
    [ATTR_SERVICE_NAME]: 'order-service',
    [ATTR_SERVICE_VERSION]: process.env.APP_VERSION ?? '0.0.0',
    'deployment.environment.name': process.env.NODE_ENV ?? 'development',
  }),

  // Export spans to the OTel Collector over gRPC. NodeSDK wraps a
  // traceExporter in a BatchSpanProcessor (buffered, background export).
  traceExporter: new OTLPTraceExporter({
    url: process.env.OTEL_EXPORTER_OTLP_ENDPOINT ?? 'http://localhost:4317',
  }),

  // Sampling: new traces are kept 10% of the time in production;
  // requests that arrive with a sampled parent follow the parent's decision,
  // so a trace is never half-recorded across services.
  // (Equivalent env config: OTEL_TRACES_SAMPLER=parentbased_traceidratio, OTEL_TRACES_SAMPLER_ARG=0.1)
  sampler: new ParentBasedSampler({
    root: new TraceIdRatioBasedSampler(process.env.NODE_ENV === 'production' ? 0.1 : 1.0),
  }),

  // Auto-instrumentation: spans for incoming HTTP/Express, outgoing http/fetch,
  // pg, redis, and more — with traceparent injected automatically.
  instrumentations: [getNodeAutoInstrumentations()],
});

sdk.start();
process.on('SIGTERM', () => { sdk.shutdown().finally(() => process.exit(0)); });  // flush buffered spans

// ── File: orders.mjs — manual spans in business logic ─────────────
import { trace, SpanStatusCode, context, propagation } from '@opentelemetry/api';

const tracer = trace.getTracer('order-service', '1.0.0');

export async function processOrder(userId, items) {
  // startActiveSpan creates a child of whatever span is active
  // (here: the auto-instrumented HTTP server span).
  return tracer.startActiveSpan('processOrder', async (span) => {
    try {
      // Attributes: queryable key-value pairs on the span.
      span.setAttributes({ 'user.id': userId, 'order.item_count': items.length });

      const inventory = await checkInventory(items);
      // Events: timestamped, log-like entries attached to the span.
      span.addEvent('inventory.checked', { allAvailable: inventory.allAvailable });

      if (!inventory.allAvailable) {
        // A business outcome, not a system error: leave status UNSET.
        span.addEvent('inventory.insufficient', { missingCount: inventory.missing.length });
        return { success: false, reason: 'insufficient_inventory' };
      }

      const payment = await chargeCard(userId, items);
      const order = await saveOrder(userId, items, payment.id);
      span.setAttribute('order.id', order.id);
      return { success: true, order };
    } catch (err) {
      span.recordException(err);                 // stack trace as a span event
      span.setStatus({ code: SpanStatusCode.ERROR, message: err.message });
      throw err;
    } finally {
      span.end();                                // always end the span
    }
  });
}

// ── Propagating trace context by hand (non-instrumented transports) ──
// Auto-instrumentation does this for http/fetch; for a custom transport
// such as a message header map, inject explicitly:
export function buildMessageHeaders() {
  const headers = {};
  propagation.inject(context.active(), headers);   // adds traceparent (+ tracestate)
  return headers;
}
